    std::string pre_assignment_shader = shader.substr(0, shader.find("\nstruct AssignmentDimensions"));
    assert(wxdouble_create(pre_assignment_shader.data(), pre_assignment_shader.size(), &context, error, sizeof(error)) == 0);
